@@ -0,0 +1,22 @@
+import Foundation
+
+struct SendMessageTool: AgentTool {
+    let name = "send_message"
+    let description = "Send a chat message to a contact through the team messaging service."
+
+    struct Input: Decodable {
+        let recipientID: String
+        let body: String
+    }
+
+    let client: MessagingClient
+
+    func run(_ input: Data) async throws -> String {
+        let args = try JSONDecoder().decode(Input.self, from: input)
+        guard !args.body.isEmpty, args.body.count <= 2000 else {
+            throw AgentToolError.invalidArgument("body must be 1 to 2000 characters")
+        }
+        let receipt = try await client.send(to: args.recipientID, text: args.body)
+        return "sent:\(receipt.id)"
+    }
+}
