@@ -8,6 +8,10 @@ import org.springframework.beans.factory.annotation.Value;
 import org.springframework.stereotype.Component;
 import org.springframework.web.filter.OncePerRequestFilter;

 import java.io.IOException;
+import java.nio.charset.StandardCharsets;
+import java.security.MessageDigest;
+import java.security.NoSuchAlgorithmException;
+import java.util.HexFormat;

 @Component
@@ -16,14 +20,26 @@ public class ApiKeyAuthFilter extends OncePerRequestFilter {
-    @Value("${billing.api.key}")
+    @Value("${billing.api.key-sha256}")
-    private String expectedKey;
+    private String expectedDigest;

     @Override
     protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain chain)
             throws ServletException, IOException {
-        String provided = request.getParameter("api_key");
-        if (expectedKey.equals(provided)) {
+        String provided = request.getHeader("X-Api-Key");
+        if (provided != null && MessageDigest.isEqual(
+                sha256Hex(provided).getBytes(StandardCharsets.UTF_8),
+                expectedDigest.getBytes(StandardCharsets.UTF_8))) {
             chain.doFilter(request, response);
         } else {
             response.sendError(HttpServletResponse.SC_UNAUTHORIZED);
         }
     }
+
+    private static String sha256Hex(String value) {
+        try {
+            byte[] digest = MessageDigest.getInstance("SHA-256")
+                    .digest(value.getBytes(StandardCharsets.UTF_8));
+            return HexFormat.of().formatHex(digest);
+        } catch (NoSuchAlgorithmException e) {
+            throw new IllegalStateException(e);
+        }
+    }
 }
