@@ -0,0 +1,27 @@
+package com.example.app.data.profile
+
+import java.util.concurrent.ConcurrentHashMap
+
+class ProfileCache(private val ttlMillis: Long = 300_000L) {
+
+    private class Entry(val profile: Profile, val storedAt: Long)
+
+    private val entries = ConcurrentHashMap<String, Entry>()
+
+    fun get(userId: String): Profile? {
+        val entry = entries[userId] ?: return null
+        if (System.currentTimeMillis() - entry.storedAt > ttlMillis) {
+            entries.remove(userId, entry)
+            return null
+        }
+        return entry.profile
+    }
+
+    fun put(userId: String, profile: Profile) {
+        entries[userId] = Entry(profile, System.currentTimeMillis())
+    }
+
+    fun invalidate(userId: String) {
+        entries.remove(userId)
+    }
+}
