@@ -0,0 +1,24 @@
+package com.example.app.data.cache
+
+import java.util.concurrent.ConcurrentHashMap
+
+class ProductCache<T>(private val ttlMillis: Long) {
+    private data class Entry<T>(val value: T, val storedAt: Long)
+
+    private val entries = ConcurrentHashMap<String, Entry<T>>()
+
+    fun get(key: String, now: Long = System.currentTimeMillis()): T? {
+        val entry = entries[key] ?: return null
+        if (now - entry.storedAt > ttlMillis) {
+            entries.remove(key)
+            return null
+        }
+        return entry.value
+    }
+
+    fun put(key: String, value: T, now: Long = System.currentTimeMillis()) {
+        entries[key] = Entry(value, now)
+    }
+
+    fun clear() = entries.clear()
+}
